/**
 * The Feats screen: Jonh's long-term goal list (rules/feats.ts), grouped, each with a progress bar
 * and the cosmetics it earns. Pure DOM; the scene supplies the rows and reward art.
 */
export interface FeatRewardView {
  name: string;
  /** Preview markup generated by our own art code (an <img> or inline SVG). */
  art: string;
  /** "hat", "outfit" or "cannon", for the caption. */
  kind: string;
}

export interface FeatRowView {
  id: string;
  name: string;
  hint: string;
  current: number;
  target: number;
  done: boolean;
  rewards: FeatRewardView[];
}

export interface FeatsOptions {
  groups: ReadonlyArray<{ title: string; rows: FeatRowView[] }>;
  onBack: () => void;
  /** Opens the wardrobe (to try on what the feats earned). */
  onWardrobe?: () => void;
}

const el = <K extends keyof HTMLElementTagNameMap>(tag: K, className = '', text = ''): HTMLElementTagNameMap[K] => {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text) node.textContent = text;
  return node;
};

export function buildFeats(content: HTMLElement, signal: AbortSignal, options: FeatsOptions): void {
  const rows = options.groups.flatMap(g => g.rows);
  const done = rows.filter(r => r.done).length;
  content.appendChild(el('h2', '', 'Feats'));
  const summary = el('div', 'campaign-tally feats-tally');
  summary.append(el('span', 'tally-stars', `${done} / ${rows.length}`), el('span', '', 'done. Each one is a story Jonh will not stop telling.'));
  const bar = el('div', 'tally-bar');
  bar.style.setProperty('--fill', `${rows.length ? (done / rows.length) * 100 : 0}%`);
  summary.appendChild(bar);
  content.appendChild(summary);

  const list = el('div', 'feats-list');
  for (const group of options.groups) {
    const section = el('section', 'feats-group');
    section.appendChild(el('h3', 'feats-group-title', group.title));
    const ul = el('ul', 'feats-rows');
    for (const row of group.rows) {
      const li = el('li', `feat${row.done ? ' done' : ''}`);
      const medal = el('span', 'feat-medal');
      medal.setAttribute('aria-hidden', 'true');
      const text = el('div', 'feat-text');
      const title = el('strong', '', row.name);
      text.append(title, el('span', 'feat-hint', row.hint));
      const meter = el('div', 'feat-meter');
      const fill = el('span', 'feat-fill');
      fill.style.width = `${(row.current / row.target) * 100}%`;
      meter.appendChild(fill);
      const count = el('span', 'feat-count', row.done ? 'Done' : `${row.current} / ${row.target}`);
      const progress = el('div', 'feat-progress');
      progress.append(meter, count);
      text.appendChild(progress);
      li.setAttribute('aria-label', `${row.name}: ${row.hint} ${row.done ? 'Done.' : `${row.current} of ${row.target}.`}${row.rewards.length ? ` Earns ${row.rewards.map(r => `the ${r.name} ${r.kind}`).join(' and ')}.` : ''}`);
      const rewards = el('div', 'feat-rewards');
      if (row.rewards.length === 0) rewards.appendChild(el('span', 'feat-badge', 'Bragging rights'));
      for (const reward of row.rewards) {
        const chip = el('span', `feat-reward feat-reward-${reward.kind}`);
        const art = el('span', 'feat-reward-art');
        art.innerHTML = reward.art;
        chip.append(art, el('small', '', reward.name));
        rewards.appendChild(chip);
      }
      li.append(medal, text, rewards);
      ul.appendChild(li);
    }
    section.appendChild(ul);
    list.appendChild(section);
  }
  content.appendChild(list);

  const actions = el('div', 'menu-actions');
  if (options.onWardrobe) {
    const wardrobe = el('button', 'btn', 'Wardrobe');
    wardrobe.type = 'button';
    wardrobe.addEventListener('click', options.onWardrobe, { signal });
    actions.appendChild(wardrobe);
  }
  const back = el('button', 'btn btn-primary', 'Back');
  back.type = 'button';
  back.addEventListener('click', options.onBack, { signal });
  actions.appendChild(back);
  content.appendChild(actions);
  back.focus();
}
